export type Locale = keyof typeof messageCatalog
export type MessageKey = keyof typeof messageCatalog.zh

type PlaceholderNames<S extends string> = S extends `${string}{${infer Name}}${infer Rest}`
  ? Name | PlaceholderNames<Rest>
  : never

type TemplateFor<K extends MessageKey> = typeof messageCatalog.zh[K]
export type MessageParams<K extends MessageKey> = [PlaceholderNames<TemplateFor<K>>] extends [never]
  ? undefined
  : Readonly<Record<PlaceholderNames<TemplateFor<K>>, string | number>>

export type Translator = {
  <K extends MessageKey>(key: K, params?: MessageParams<K>): string
  /** Read the host locale through the boundary, never from a message key. */
  locale?: () => Locale
}

export const hostDictionaries: Record<string, Record<string, string>> = {
  zh: { ...messageCatalog.zh },
  en: { ...messageCatalog.en },
}

function formatMessage(template: string, params: Readonly<Record<string, string | number>> | undefined): string {
  if (params === undefined) return template
  return template.replace(/\{([A-Za-z0-9_.-]+)\}/g, (match, name: string) => name in params ? String(params[name]) : match)
}

export function createTranslator(bind: Translator, fallbackLocale?: Locale, locale?: () => Locale): Translator
export function createTranslator(bind: (key: string) => string, fallbackLocale?: Locale, locale?: () => Locale): Translator
export function createTranslator(bind: Translator | ((key: string) => string), fallbackLocale: Locale = 'zh', locale?: () => Locale): Translator {
  const translator = ((key: MessageKey, params?: Readonly<Record<string, string | number>>) => {
    let template: string
    try { template = bind(key as never) } catch { template = key }
    if (template === key || template === '') template = messageCatalog[fallbackLocale][key]
    return formatMessage(template ?? key, params)
  }) as Translator
  translator.locale = locale
  return translator
}

export function createStaticTranslator(locale: Locale): Translator {
  return createTranslator(key => messageCatalog[locale][key as MessageKey], locale, () => locale)
}

export const defaultTranslator = createStaticTranslator('zh')

export interface OperationMessageInput {
  /** Legacy server text is retained for diagnostics and older hosts. */
  message?: string
  /** New server-side key/params metadata, optional for wire compatibility. */
  messageKey?: OperationMessageKey | string
  messageParams?: OperationMessageParams
}

