function translateKnownOperationMessage(t: Translator, key: string | undefined, params?: OperationMessageParams): string | undefined {
  if (key === undefined || !Object.prototype.hasOwnProperty.call(messageCatalog.zh, key)) return undefined
  const translated = t(key as MessageKey, params as never)
  // Identity translators are useful in old test/host shims. Do not replace
  // their raw message with a catalog key when they do not translate it.
  return translated === key ? undefined : translated
}

/** Translate first-party operation text while leaving unknown diagnostics byte-for-byte unchanged. */
export function operationMessage(input: OperationMessageInput, t: Translator = defaultTranslator): string | undefined {
  const typed = translateKnownOperationMessage(t, input.messageKey, input.messageParams)
  if (typed !== undefined) return typed
  if (input.message === undefined) return undefined
  for (const rule of legacyOperationMessageRules) {
    const params = rule.match(input.message)
    if (params !== null) {
      const translated = translateKnownOperationMessage(t, rule.key, params)
      if (translated !== undefined) return translated
    }
  }
  return input.message
}

/** Format locale-sensitive UI values at the translator boundary. */
export function formatDateLabel(value: string, t: Translator = defaultTranslator): string {
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return t('common.dateUnknown')
  const locale = t.locale?.() === 'en' ? 'en-US' : 'zh-CN'
  return new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(date)
}

/** Select an author-provided localized name without translating source data. */
export function localizedSkinName(name: { zh: string; en: string }, t: Translator = defaultTranslator): string {
  const preferred = t.locale?.() === 'en' ? name.en : name.zh
  return preferred || name.zh || name.en
}

export function catalogKeys(locale: Locale = 'zh'): MessageKey[] {
  return Object.keys(messageCatalog[locale]) as MessageKey[]
}

export function assertCatalogParity(): void {
  const zh = new Set(Object.keys(messageCatalog.zh))
  const en = new Set(Object.keys(messageCatalog.en))
  const missingInEnglish = [...zh].filter(key => !en.has(key))
  const missingInChinese = [...en].filter(key => !zh.has(key))
  if (missingInEnglish.length > 0 || missingInChinese.length > 0) {
    throw new Error(`message catalog mismatch: missing en=${missingInEnglish.join(',')}; missing zh=${missingInChinese.join(',')}`)
  }
}

assertCatalogParity()